  "channels.agent.ready": "Created",
  "channels.agent.create": "Create the receptionist",
  "channels.agent.other.title": "Use another ElevenLabs agent",
  "channels.agent.other.help": "Paste the ID of an agent you already made in ElevenLabs. Connecting it changes nothing inside that agent: its voice, instructions and name stay as you made them, and the website widget, Try the assistant and WhatsApp start using it. CallsDash never writes to it, not even when clinic knowledge, hours or doctors change. Booking needs the CallsDash tools, which only arrive through the collapsed \"Advanced: let CallsDash manage this agent\" that appears after you connect; that replaces the agent's text with CallsDash's, so leave it closed to keep your own.",
  "channels.agent.other.id": "Agent ID",
  "channels.agent.other.use": "Use this agent",
  "channels.agent.other.before": "Agents this client used before",
