  "channels.saved.agent_switched": "Now using that agent. Nothing was changed inside it.",
  "channels.err.agent_bad_id": "That is not an agent ID. It starts with agent_ and has no spaces.",
  "channels.err.agent_same": "This client already uses that agent.",
