  "channels.err.agent_not_found": "ElevenLabs has no agent with that ID under the account of this API key. Check the ID, and that it is in the same ElevenLabs account.",
  "channels.err.agent_in_use": "Another client already uses that agent. Two clinics must not share one agent.",
  "channels.err.agent_failed": "ElevenLabs could not be reached to check the agent. Try again in a minute.",
  "channels.agent.connected": "Connected agent",
  "channels.agent.connected.help": "This client uses an agent you connected by ID. CallsDash does not change it: no Sync, no automatic updates, and Save and apply in the Assistant studio only keeps the setting here. Conversations, bookings and costs still appear in CallsDash.",
  "channels.agent.takeover.title": "Advanced: let CallsDash manage this agent",
  "channels.agent.takeover.warn": "Pressing this replaces the agent's instructions, greeting, voices, settings and knowledge in ElevenLabs with what CallsDash holds, and adds the booking tools. Your hand-made settings in ElevenLabs are lost. To keep them, do not press it; to try it safely, make a copy of the agent in ElevenLabs first.",
  "channels.agent.takeover.tick": "I understand my settings in ElevenLabs will be replaced",
  "channels.agent.takeover.button": "Replace the agent's settings",
  "channels.err.connected": "This is a connected agent, so nothing was sent to ElevenLabs. The change is kept in CallsDash only.",
  "try.connected.admin": "Connected agent: CallsDash does not change it, so what you hear is exactly what you set in ElevenLabs.",
  "studio.connected": "This client uses a connected agent. Saving here keeps the settings in CallsDash only and sends nothing to ElevenLabs. To let CallsDash manage the agent, use the advanced section on the page",
  "dup.open": "Duplicate client",
  "dup.title": "Duplicate client",
  "dup.help": "Makes a new client with the same look, opening hours, closed days, rules, permissions and assistant instructions and options. Patients, bookings, conversations, credits, sign-ins and every outside connection (ElevenLabs agent, Google calendars, WhatsApp, Instagram, phone) are never copied.",
  "dup.domainHelp": "A website can belong to only one client. Leave it empty if the new clinic has no website yet and add it later.",
  "dup.copyDoctors": "Copy the {n} doctor(s): names, specialties, About text and weekly hours. Their Google calendars and leave are not copied.",
  "dup.copyKnowledge": "Copy the {n} knowledge item(s). The old clinic's name is replaced by the new name; check the facts yourself.",
  "dup.create": "Create the copy",
  "dup.done": "The copy is ready: {doctors} doctor(s) and {knowledge} knowledge item(s) copied, and the old name replaced {renamed} time(s). Nothing was sent to ElevenLabs.",
  "dup.careful.title": "Be careful with these",
  "dup.c.agent": "Assistant: the copy has no ElevenLabs agent yet. On Channels press \"Create the receptionist\" for a new one, or connect an agent of your own by its ID. Never let two clients use the same agent: calls and bookings would land in the wrong clinic.",
  "dup.c.calendar": "Google Calendar: every doctor needs their own calendar, shared with the service account. Never reuse another clinic's calendar.",
  "dup.c.channels": "WhatsApp, Instagram and phone: each client needs its own number or account, and its own message template. Connect them on Channels.",
  "dup.c.people": "People: no sign-ins were copied. Add the manager, receptionists and doctors on Users or Team.",
  "dup.c.credits": "Credits: the copy starts only with the first month of the package you picked. Check the wallet before it goes live.",
  "dup.c.texts": "Texts: read the instructions, greeting, knowledge, hours, address and phone numbers for facts that belong to the old clinic. The logo, cover picture and support contacts were not copied.",
  "dup.c.website": "Website: a website address belongs to one client only. Add the new clinic's address on its Business tab when it has one.",
