  "customers.lookup.phone": "By phone number",
  "customers.lookup.phone.help": "Best when customers call or write from their own phone. The assistant greets them by first name; their notes and past conversations stay private until they say their CPR number.",
  "customers.lookup.cpr": "By CPR number",
  "customers.lookup.cpr.help": "The assistant asks for the CPR number and finds the customer whatever phone they use. A matching CPR number is enough to share their notes and past conversations.",
  "customers.lookup.note": "The assistant is updated automatically after you save. Customers who have no CPR number on file cannot be found by CPR number, so add it on their record.",
  "customers.lookup.saved": "Saved. The assistant now finds customers this way.",
  "nav.catalogue": "Catalogue",
  "catalogue.title": "Catalogue",
  "catalogue.help": "What you offer, with details and a photo. When a customer asks about it, the assistant looks it up here and answers from what you wrote. In the website chat it can also show the photo.",
  "catalogue.guide.title": "How the catalogue and photos work",
  "catalogue.guide.1": "Press \"Add an item\", write its name and details, and choose a photo.",
  "catalogue.guide.2": "Add the Arabic name and details too, so Arabic customers get Arabic answers.",
  "catalogue.guide.3": "Under Extra words, add other names people use for it, separated by commas.",
  "catalogue.guide.4": "Test it: ask the assistant about the item in \"Try the assistant\" on the Home page.",
  "catalogue.guide.note": "Photos show in the website chat only. On WhatsApp, Instagram and phone calls the assistant describes the item in words. The assistant must be updated once (a manager presses \"Update the assistant\") before it can use the catalogue.",
  "catalogue.search": "Search by name or details",
