  "channels.saved.wa_photo_token": "The photo access token was saved.",
  "channels.saved.wa_photo_test": "Test photo sent. It should arrive on that WhatsApp number in a moment.",
  "channels.wa.photo.title": "Photos in WhatsApp chats",
  "channels.wa.photo.on": "Photo sending on",
  "channels.wa.photo.off": "Link only",
  "channels.wa.photo.help": "Without this, when a customer asks about an item on WhatsApp the assistant sends a link that shows the photo as a preview. With an access token from Meta, the assistant sends the photo itself in the chat. This is optional.",
  "channels.wa.photo.guide.title": "How to get the Meta access token for photos",
  "channels.wa.photo.s1": "Open developers.facebook.com/apps, sign in with the Facebook account that manages the clinic's WhatsApp, and press \"Create app\". Name it \"CallsDash photos\", choose the clinic's business if asked, pick the type \"Business\" (or the use case \"Other\"), and press \"Create app\".",
  "channels.wa.photo.s2": "Open business.facebook.com/settings (Business settings) and make sure the clinic's business is selected at the top left.",
  "channels.wa.photo.s3": "In the left menu press \"Users\", then \"System users\", then \"Add\". Type the name \"CallsDash\", choose the role \"Admin\", and press \"Create system user\".",
  "channels.wa.photo.s4": "With CallsDash selected, press \"Add assets\", choose \"Apps\", tick the app \"CallsDash photos\", switch on \"Full control\", and press \"Save changes\".",
  "channels.wa.photo.s5": "Press \"Add assets\" again, choose \"WhatsApp accounts\", tick the clinic's WhatsApp account, switch on \"Full control\", and press \"Save changes\".",
  "channels.wa.photo.s6": "Press \"Generate token\" at the top right. Choose the app \"CallsDash photos\", set the expiry to \"Never\", tick \"whatsapp_business_messaging\" and \"whatsapp_business_management\", press \"Generate token\", then press \"Copy\".",
  "channels.wa.photo.s7": "Click in the box \"WhatsApp access token\" below, paste with Ctrl+V (on a phone, hold and press Paste), and press Save. Then run the test below.",
  "channels.wa.photo.note": "The names of Meta's buttons change from time to time. If a screen looks different, send a screenshot (never a password) and the steps will be updated.",
  "channels.wa.photo.token": "WhatsApp access token",
  "channels.wa.photo.item": "Photo to send",
  "channels.wa.photo.test": "Send a test photo",
  "channels.wa.photo.testHelp": "WhatsApp only allows a photo inside 24 hours after the customer last wrote. Before testing, send any message from your phone to the clinic's WhatsApp number, then press the button within 24 hours.",
  "channels.wa.photo.noItems": "Add a catalogue item with a photo for this client first (the client's Catalogue page), then you can send a test photo.",
  "channels.wa.photo.bad_token": "That does not look like an access token. It is one long line of letters and numbers with no spaces.",
  "channels.wa.photo.no_token": "Save the access token first.",
  "channels.wa.photo.no_phone_id": "Fill in the phone number ID above first.",
  "channels.wa.photo.no_recipient": "That does not look like a phone number.",
  "channels.wa.photo.no_item": "Choose an item that has a photo and is visible.",
  "channels.wa.photo.no_photo": "That item has no photo.",
  "channels.wa.photo.format": "WhatsApp shows JPEG and PNG photos only. Upload this item's photo again (it is converted to JPEG automatically).",
  "channels.wa.photo.channel_off": "This client was not found.",
  "channels.wa.photo.failed": "Meta refused the photo.",
  "channels.wa.photo.hint.token": "The access token is not valid or has expired. Create a new one with the steps above and save it.",
  "channels.wa.photo.hint.window": "The customer has not written in the last 24 hours. Send a message from your phone to the clinic's number, then try again.",
  "channels.wa.photo.hint.permission": "The token cannot use this WhatsApp account. Check that the account was added to the system user with Full control, and that both permissions were ticked.",
  "customers.privacy": "Tell customers that the clinic keeps their details. You can say it in the assistant's greeting or on your website.",
  "channels.agent.sync": "Sync to ElevenLabs",
  "channels.agent.help": "Sends the prompt, voices, knowledge base, booking tools and allowed websites to ElevenLabs. Safe to run again at any time; run it after changing anything for this client.",
