  "prof.b.recommended.name": "Balanced for a clinic (suggested)",
  "prof.b.recommended.who": "The setting we suggest for most clinics: good answers, fast replies and a sensible cost.",
  "prof.b.recommended.impact": "A proven AI model and the fast voice engines, normal turn-taking, calls limited to 15 minutes, safety on, bursting allowed so no call is missed.",
  "prof.b.recommended.why1": "Gemini 2.5 Flash is inexpensive and is the model CallsDash uses unless you choose another.",
  "prof.b.recommended.why2": "A reply limit of 600 leaves room for a booking without cutting it off.",
  "prof.b.recommended.why3": "A short “one moment please” after 3 seconds avoids silence while a slot is checked.",
  "prof.b.lowcost.name": "Lowest cost",
  "prof.b.lowcost.who": "For a quiet clinic or a trial month where every dinar counts.",
  "prof.b.lowcost.impact": "A lighter AI model, shorter replies and calls, faster speech, fewer checks, and no calls above the plan's limit. Cheaper, but a little less careful: test booking in Arabic before you rely on it.",
  "prof.b.lowcost.why1": "Gemini 2.5 Flash Lite costs a fraction of the standard model.",
  "prof.b.lowcost.why2": "Calls end after 8 minutes or 15 seconds of silence, and bursting is off, so a stuck call cannot run up the bill.",
  "prof.b.lowcost.why3": "Summaries in English and two quality checks off mean less to read and less to pay for.",
  "prof.b.premium.name": "Best quality",
  "prof.b.premium.who": "For a clinic that wants the most natural voice and the most careful answers and accepts a higher cost.",
  "prof.b.premium.impact": "A top AI model, the newest voice engine with expressive speech, longer calls and more patience. Higher cost per minute. Not yet tried on a real account: apply it, try the assistant, and go back if you prefer the balanced setting.",
  "prof.b.premium.why1": "Claude Sonnet 5.5 is ElevenLabs' most accurate model for tools and long instructions.",
  "prof.b.premium.why2": "The v4 Turbo voice is ElevenLabs' newest, with expressive speech, at a slightly slower pace.",
  "prof.b.premium.why3": "A daily limit of 300 keeps the higher cost under control.",
  "prof.b.patient.name": "Patient and clear",
  "prof.b.patient.who": "For callers who speak slowly, are older, or call from noisy places.",
  "prof.b.patient.impact": "The assistant waits longer, speaks a little slower and more steadily, and lets calls run longer. A bit more cost per call, fewer interruptions.",
  "prof.b.patient.why1": "Patient turn-taking and a 10 second wait stop it talking over callers who pause.",
  "prof.b.patient.why2": "Speed 0.9 and higher stability are easier to follow on a poor line.",
  "prof.b.patient.why3": "45 seconds of silence before hanging up gives callers time to find their details.",
