  "channels.agent.create": "إنشاء موظفة الاستقبال",
  "channels.agent.other.title": "استخدام مساعد آخر من ElevenLabs",
  "channels.agent.other.help": "الصق معرّف مساعد أنشأته بنفسك في ElevenLabs. الربط لا يغيّر شيئًا داخل ذلك المساعد: صوته وتعليماته واسمه تبقى كما صنعتها، ويبدأ استخدامه في أداة الموقع و«جرّب المساعد» وواتساب. لا تكتب CallsDash فيه أبدًا، حتى عند تغيّر معرفة العيادة أو مواعيدها أو أطبائها. الحجز يحتاج أدوات CallsDash التي لا تصل إلا عبر قسم «متقدم: السماح لـ CallsDash بإدارة هذا المساعد» المطوي الذي يظهر بعد الربط، وهذا يستبدل نص المساعد بنص CallsDash، فاتركه مغلقًا للإبقاء على نصك.",
