  "channels.agent.connected.help": "يستخدم هذا العميل مساعدًا ربطته بمعرّفه. لا تغيّره CallsDash: لا مزامنة ولا تحديث تلقائي، و«حفظ وتطبيق» في استوديو المساعد يحفظ الإعداد هنا فقط. تظهر المحادثات والحجوزات والتكاليف في CallsDash كالمعتاد.",
  "channels.agent.takeover.title": "متقدم: السماح لـ CallsDash بإدارة هذا المساعد",
  "channels.agent.takeover.warn": "الضغط هنا يستبدل تعليمات المساعد وتحيته وأصواته وإعداداته ومعرفته في ElevenLabs بما تحتفظ به CallsDash، ويضيف أدوات الحجز. ستضيع إعداداتك اليدوية في ElevenLabs. للإبقاء عليها لا تضغطه؛ وللتجربة بأمان انسخ المساعد في ElevenLabs أولاً.",
