  "dup.open": "نسخ العميل",
  "dup.title": "نسخ العميل",
  "dup.help": "ينشئ عميلاً جديداً بنفس المظهر وساعات العمل وأيام الإغلاق والقواعد والصلاحيات وتعليمات المساعد وخياراته. لا يُنسخ أبداً المرضى ولا الحجوزات ولا المحادثات ولا الرصيد ولا حسابات الدخول ولا أي ربط خارجي (مساعد ElevenLabs وتقاويم Google وواتساب وإنستغرام والهاتف).",
