  "dup.done": "النسخة جاهزة: نُسخ {doctors} من الأطباء و{knowledge} من عناصر المعرفة، واستُبدل الاسم القديم {renamed} مرة. لم يُرسل شيء إلى ElevenLabs.",
  "dup.careful.title": "انتبه لهذه النقاط",
  "dup.c.agent": "المساعد: ليس للنسخة مساعد في ElevenLabs بعد. في صفحة القنوات اضغط «إنشاء موظفة الاستقبال» لإنشاء مساعد جديد، أو اربط مساعداً خاصاً بك بمعرّفه. لا تجعل عميلين يستخدمان المساعد نفسه أبداً: ستذهب المكالمات والحجوزات إلى عيادة خاطئة.",
  "dup.c.calendar": "تقويم Google: لكل طبيب تقويمه الخاص، مشاركاً مع حساب الخدمة. لا تعد استخدام تقويم عيادة أخرى أبداً.",
  "dup.c.channels": "واتساب وإنستغرام والهاتف: لكل عميل رقمه أو حسابه وقالب رسالته. اربطها من صفحة القنوات.",
  "dup.c.people": "الأشخاص: لم تُنسخ حسابات الدخول. أضف المدير والاستقبال والأطباء من صفحة المستخدمين أو الفريق.",
  "dup.c.credits": "الرصيد: تبدأ النسخة بالشهر الأول من الباقة التي اخترتها فقط. راجع المحفظة قبل التشغيل.",
  "dup.c.texts": "النصوص: اقرأ التعليمات والتحية والمعرفة والساعات والعنوان وأرقام الهاتف بحثاً عن معلومات تخص العيادة القديمة. لم يُنسخ الشعار ولا صورة الغلاف ولا بيانات الدعم.",
  "dup.c.website": "الموقع: عنوان الموقع يتبع عميلاً واحداً فقط. أضف عنوان العيادة الجديدة في تبويب النشاط حين يكون لها موقع.",
  "guide.hide": "إخفاء هذا الدليل. يمكنك إعادته من صفحة الحساب.",
  "account.guides.title": "الأدلة والنصائح",
