  "catalogue.help": "ما تقدّمونه مع التفاصيل وصورة. عندما يسأل عميل عنه يبحث المساعد هنا ويجيب مما كتبتموه. وفي محادثة الموقع يستطيع عرض الصورة أيضاً.",
