  "channels.saved.wa_photo_token": "تم حفظ رمز الوصول الخاص بالصور.",
  "channels.saved.wa_photo_test": "تم إرسال صورة تجريبية. يفترض أن تصل إلى رقم واتساب هذا بعد لحظات.",
  "channels.wa.photo.title": "الصور في محادثات واتساب",
  "channels.wa.photo.on": "إرسال الصور مفعّل",
  "channels.wa.photo.off": "رابط فقط",
  "channels.wa.photo.help": "بدون هذا الإعداد، عندما يسأل عميل عن عنصر في واتساب يرسل المساعد رابطاً تظهر فيه الصورة كمعاينة. وبرمز وصول من Meta يرسل المساعد الصورة نفسها داخل المحادثة. هذا الإعداد اختياري.",
  "channels.wa.photo.guide.title": "كيف تحصلون على رمز وصول Meta للصور",
  "channels.wa.photo.s1": "افتحوا developers.facebook.com/apps وسجّلوا الدخول بحساب فيسبوك الذي يدير واتساب العيادة، ثم اضغطوا «Create app». سمّوه «CallsDash photos»، واختاروا نشاط العيادة التجاري إن طُلب، واختاروا النوع «Business» (أو حالة الاستخدام «Other»)، ثم اضغطوا «Create app».",
  "channels.wa.photo.s2": "افتحوا business.facebook.com/settings (إعدادات النشاط التجاري) وتأكدوا أن نشاط العيادة مختار في أعلى اليسار.",
  "channels.wa.photo.s3": "من القائمة اليسرى اضغطوا «Users» ثم «System users» ثم «Add». اكتبوا الاسم «CallsDash» واختاروا الدور «Admin» ثم اضغطوا «Create system user».",
  "channels.wa.photo.s4": "والمستخدم CallsDash محدد، اضغطوا «Add assets» واختاروا «Apps» وضعوا علامة على التطبيق «CallsDash photos» وشغّلوا «Full control» ثم اضغطوا «Save changes».",
  "channels.wa.photo.s5": "اضغطوا «Add assets» مرة أخرى، واختاروا «WhatsApp accounts» وضعوا علامة على حساب واتساب العيادة وشغّلوا «Full control» ثم اضغطوا «Save changes».",
  "channels.wa.photo.s6": "اضغطوا «Generate token» في أعلى اليمين. اختاروا التطبيق «CallsDash photos» واجعلوا الانتهاء «Never» وضعوا علامة على «whatsapp_business_messaging» و«whatsapp_business_management» ثم اضغطوا «Generate token» ثم «Copy».",
  "channels.wa.photo.s7": "اضغطوا داخل خانة «رمز وصول واتساب» أدناه والصقوا بـ Ctrl+V (على الهاتف اضغطوا مطولاً ثم «لصق») ثم اضغطوا حفظ. بعدها شغّلوا الاختبار أدناه.",
  "channels.wa.photo.note": "تتغير أسماء أزرار Meta من وقت لآخر. إن اختلفت الشاشة عندكم فأرسلوا لقطة شاشة (دون كلمة مرور) وسنحدّث الخطوات.",
  "channels.wa.photo.token": "رمز وصول واتساب",
  "channels.wa.photo.item": "الصورة المراد إرسالها",
  "channels.wa.photo.test": "إرسال صورة تجريبية",
  "channels.wa.photo.testHelp": "يسمح واتساب بإرسال الصورة خلال 24 ساعة من آخر رسالة كتبها العميل فقط. قبل الاختبار أرسلوا أي رسالة من هاتفكم إلى رقم واتساب العيادة، ثم اضغطوا الزر خلال 24 ساعة.",
  "channels.wa.photo.noItems": "أضيفوا أولاً عنصراً بصورة في كتالوج هذا العميل (صفحة الكتالوج لدى العميل) ثم يمكنكم إرسال صورة تجريبية.",
