  "channels.wa.photo.hint.window": "لم يكتب العميل خلال آخر 24 ساعة. أرسلوا رسالة من هاتفكم إلى رقم العيادة ثم حاولوا مجدداً.",
  "channels.wa.photo.hint.permission": "لا يستطيع الرمز استخدام حساب واتساب هذا. تأكدوا أن الحساب أُضيف إلى مستخدم النظام بصلاحية Full control وأن الصلاحيتين محددتان.",
