  "channels.agent.extras": "يُضبط أيضاً في ElevenLabs: فحوص الأمان ضد التلاعب والخروج عن الموضوع، إنهاء المكالمات بشكل صحيح، حفظ التسجيلات حسب أيام الاحتفاظ لدى العميل، حد يومي، تحليل المكالمات (النية والاستعجال والمزاج)، فحوص الجودة، أسماء لتحسين التعرف على الكلام، وأداة الموقع بألوان العميل.",
