  "prof.b.recommended.name": "متوازن للعيادة (مقترح)",
  "prof.b.recommended.who": "الإعداد الذي نقترحه لمعظم العيادات: إجابات جيدة وردود سريعة وتكلفة معقولة.",
  "prof.b.recommended.impact": "نموذج ذكاء اصطناعي مجرَّب ومحركات صوت سريعة، وتبادل كلام عادي، ومكالمات حتى 15 دقيقة، والسلامة مفعّلة، والتجاوز مسموح كي لا تفوت مكالمة.",
  "prof.b.recommended.why1": "Gemini 2.5 Flash رخيص، وهو النموذج الذي يستخدمه CallsDash ما لم تختر غيره.",
  "prof.b.recommended.why2": "حد الرد 600 يترك مجالًا للحجز دون قطعه.",
  "prof.b.recommended.why3": "عبارة «لحظة من فضلك» بعد 3 ثوانٍ تتجنب الصمت أثناء فحص الموعد.",
  "prof.b.lowcost.name": "الأقل تكلفة",
  "prof.b.lowcost.who": "لعيادة هادئة أو شهر تجريبي يهم فيه كل دينار.",
  "prof.b.lowcost.impact": "نموذج ذكاء اصطناعي أخف وردود ومكالمات أقصر وكلام أسرع وفحوص أقل ولا مكالمات فوق حد الباقة. أرخص لكنه أقل دقة قليلًا: جرّب الحجز بالعربية قبل الاعتماد عليه.",
  "prof.b.lowcost.why1": "Gemini 2.5 Flash Lite يكلف جزءًا من النموذج المعتاد.",
  "prof.b.lowcost.why2": "تنتهي المكالمات بعد 8 دقائق أو 15 ثانية صمت، ويُوقَف التجاوز، فلا تستهلك مكالمة عالقة الفاتورة.",
  "prof.b.lowcost.why3": "ملخصات بالإنجليزية وإيقاف فحصين للجودة يعني قراءة أقل وتكلفة أقل.",
  "prof.b.premium.name": "أعلى جودة",
  "prof.b.premium.who": "لعيادة تريد أطبع صوت وأدق إجابات وتقبل تكلفة أعلى.",
  "prof.b.premium.impact": "نموذج ذكاء اصطناعي من الطراز الأول وأحدث محرك صوت بكلام معبّر ومكالمات أطول وصبر أكثر. تكلفة أعلى للدقيقة. لم يُجرَّب بعد على حساب حقيقي: طبّقه وجرّب المساعد وارجع إلى الإعداد المتوازن إن فضّلته.",
  "prof.b.premium.why1": "Claude Sonnet 5.5 هو أدق نماذج ElevenLabs للأدوات والتعليمات الطويلة.",
  "prof.b.premium.why2": "صوت v4 Turbo هو الأحدث لدى ElevenLabs، بكلام معبّر وبإيقاع أبطأ قليلًا.",
  "prof.b.premium.why3": "حد يومي 300 يبقي التكلفة الأعلى تحت السيطرة.",
  "prof.b.patient.name": "صبور وواضح",
  "prof.b.patient.who": "للمتصلين الذين يتكلمون ببطء أو كبار السن أو من أماكن صاخبة.",
  "prof.b.patient.impact": "ينتظر المساعد أطول ويتكلم أبطأ وأثبت قليلًا ويترك المكالمات تستمر أطول. تكلفة أعلى قليلًا للمكالمة ومقاطعات أقل.",
  "prof.b.patient.why1": "تبادل الكلام الصبور وانتظار 10 ثوانٍ يمنعانه من مقاطعة من يتوقفون.",
  "prof.b.patient.why2": "سرعة 0.9 وثبات أعلى أسهل في المتابعة على خط ضعيف.",
